const KG_SOURCE=window.KG_DATA||{directory:[],topicMetrics:{},relations:[],metricInfo:{},meta:{}};
const KG_LEVEL_NAMES={1:'责任中心',2:'业务域',3:'对象',4:'主题'};
const KG_LEVEL_FIELDS={1:'责任中心',2:'业务域',3:'对象',4:'主题'};
function kgUnique(values){return [...new Set(values.filter(Boolean))]}
function kgMetrics(topic){return KG_SOURCE.topicMetrics[topic]||[]}
function kgMetricTopics(metric){return Object.entries(KG_SOURCE.topicMetrics).filter(([,metrics])=>metrics.includes(metric)).map(([topic])=>topic)}
function kgKey(level,parts){return `${level}:${parts.join('/')}`}
function kgScope(){return state.graphScope||{level:4,parts:['区域TOB','政企','渠道','伙伴激励']}}
function kgScopeActive(level,parts){const scope=kgScope();return scope.level===level&&scope.parts.join('/')===parts.join('/')}
function kgRowsForParts(parts){return KG_SOURCE.directory.filter(row=>parts.every((value,i)=>row[KG_LEVEL_FIELDS[i+1]]===value))}
function kgChildValues(rows,level){return kgUnique(rows.map(row=>row[KG_LEVEL_FIELDS[level]]))}
function kgTreeBranch(label,level,parts,rows,content){const key=kgKey(level,parts),open=state.graphExpanded?.has(key);return `<div class='kg-tree-branch level-${level}'><div class='kg-tree-row ${kgScopeActive(level,parts)?'active':''}'><button class='kg-tree-toggle' type='button' data-kg-toggle='${esc(key)}' aria-label='${open?'收起':'展开'}${esc(label)}' aria-expanded='${open}'>${open?'−':'+'}</button><button class='kg-tree-scope' type='button' data-kg-scope-level='${level}' data-kg-scope-parts='${esc(JSON.stringify(parts))}'><span class='kg-level'>L${level}</span><span class='kg-tree-label'>${esc(label)}</span><small>${level===3?kgChildValues(rows,4).length:rows.length}</small></button></div><div class='kg-tree-children' ${open?'':'hidden'}>${content}</div></div>`}
function kgDirectoryTree(){const rows=KG_SOURCE.directory;return kgChildValues(rows,1).map(l1=>{const r1=rows.filter(x=>x['责任中心']===l1),p1=[l1];const c1=kgChildValues(r1,2).map(l2=>{const r2=r1.filter(x=>x['业务域']===l2),p2=[l1,l2];const c2=kgChildValues(r2,3).map(l3=>{const r3=r2.filter(x=>x['对象']===l3),p3=[l1,l2,l3];const topics=kgChildValues(r3,4).map(topic=>{const p4=[l1,l2,l3,topic];return `<button type='button' class='kg-topic ${kgScopeActive(4,p4)?'active':''}' data-kg-scope-level='4' data-kg-scope-parts='${esc(JSON.stringify(p4))}'><span class='kg-topic-dot'></span><span>${esc(topic)}</span><small>${kgMetrics(topic).length}</small></button>`}).join('');return kgTreeBranch(l3,3,p3,r3,topics)}).join('');return kgTreeBranch(l2,2,p2,r2,c2)}).join('');return kgTreeBranch(l1,1,p1,r1,c1)}).join('')}
function kgTruncate(name,max=16){return name.length>max?name.slice(0,max-1)+'…':name}
function kgNodeLines(name,max=11){if(name.length<=max)return [name];return [name.slice(0,max-1),kgTruncate(name.slice(max-1),max)]}
function kgScopeMeta(){const scope=kgScope(),rows=kgRowsForParts(scope.parts),label=scope.parts[scope.level-1]||'',topics=kgChildValues(rows,4),topicMetrics=Object.fromEntries(topics.map(topic=>[topic,kgMetrics(topic)])),metrics=kgUnique(Object.values(topicMetrics).flat()),relations=KG_SOURCE.relations.filter(x=>metrics.includes(x.source)||metrics.includes(x.target)),external=kgUnique(relations.flatMap(x=>[x.source,x.target]).filter(x=>!metrics.includes(x)));return {scope,rows,label,topics,topicMetrics,metrics,relations,external,path:scope.parts.join(' / '),type:KG_LEVEL_NAMES[scope.level]}}
function kgNodeRadius(type){return type==='root'?52:type==='topic'?42:type==='domain'||type==='object'?46:34}
function kgPolar(cx,cy,r,angle){return {x:cx+Math.cos(angle)*r,y:cy+Math.sin(angle)*r}}
function kgMetricNode(name,p,index,external=false){const selected=name===state.selectedGraphMetric,related=KG_SOURCE.relations.some(x=>x.source===name||x.target===name),lines=kgNodeLines(name,7);return `<g class='kg-node ${selected?'selected':''} ${related?'related':''} ${external?'external':''}' style='--i:${index}' role='button' tabindex='0' aria-label='查看指标 ${esc(name)}${external?'，跨主题关联指标':''}' data-metric-node='${esc(name)}' transform='translate(${p.x.toFixed(1)} ${p.y.toFixed(1)})'><title>${esc(name)}${external?'（跨主题关联）':''}</title><circle class='kg-node-halo' r='39'/><circle class='kg-node-shell' r='34'/><circle class='kg-node-dot' cx='0' cy='-25' r='3'/><text class='kg-node-kind' text-anchor='middle' y='-15'>${external?'关联指标':'指标'}</text><text class='kg-node-name' text-anchor='middle' y='${lines.length===1?6:1}'>${esc(lines[0])}</text>${lines[1]?`<text class='kg-node-name sub' text-anchor='middle' y='12'>${esc(lines[1])}</text>`:''}</g>`}
function kgDirectoryNode(label,type,p,index,attrs='',variant='topic'){const radius=kgNodeRadius(variant),lines=kgNodeLines(label,variant==='root'?8:6),interactive=attrs?`role='button' tabindex='0' ${attrs}`:`role='img' aria-label='当前${esc(type)} ${esc(label)}'`;return `<g class='kg-dir-node ${variant}' style='--i:${index}' ${interactive} transform='translate(${p.x.toFixed(1)} ${p.y.toFixed(1)})'><circle class='kg-dir-halo' r='${radius+6}'/><circle class='kg-dir-shell' r='${radius}'/><text class='kg-dir-type' text-anchor='middle' y='-10'>${esc(type)}</text><text class='kg-dir-name' text-anchor='middle' y='${lines.length===1?8:4}'>${esc(lines[0])}</text>${lines[1]?`<text class='kg-dir-name sub' text-anchor='middle' y='16'>${esc(lines[1])}</text>`:''}</g>`}
function kgEdge(path,kind='directory',index=0,arrow=false){return `<path class='kg-edge ${kind}-edge' style='--i:${index}' ${arrow?`marker-end='url(#kg-arrow)'`:''} d='${path}'/>`}
function kgSimpleLevelGraph(meta){const nextLevel=meta.scope.level+1,values=kgChildValues(meta.rows,nextLevel),width=900,height=540,cx=450,cy=270,ring=values.length===1?190:185;let edges='',nodes='';values.forEach((label,i)=>{const angle=-Math.PI/2+(Math.PI*2*i/Math.max(values.length,1)),p=kgPolar(cx,cy,ring,angle),parts=[...meta.scope.parts,label],attrs=`data-kg-scope-level='${nextLevel}' data-kg-scope-parts='${esc(JSON.stringify(parts))}' aria-label='查看${KG_LEVEL_NAMES[nextLevel]} ${esc(label)}'`;edges+=kgEdge(`M ${cx} ${cy} L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`,'directory',i);nodes+=kgDirectoryNode(label,KG_LEVEL_NAMES[nextLevel],p,i,attrs,nextLevel===3?'object':'domain')});return {width,height,body:edges+kgDirectoryNode(meta.label,meta.type,{x:cx,y:cy},0,'','root')+nodes,description:`${meta.type}${meta.label}以辐射布局连接 ${values.length} 个${KG_LEVEL_NAMES[nextLevel]}节点。`}}
function kgTopicGraph(meta){const base=kgMetrics(meta.label),relations=KG_SOURCE.relations.filter(x=>base.includes(x.source)||base.includes(x.target)),external=kgUnique(relations.flatMap(x=>[x.source,x.target]).filter(x=>!base.includes(x))),metrics=[...base,...external],size=metrics.length>30?1080:metrics.length>16?900:760,c=size/2,positions={},rings=metrics.length>30?[{n:12,r:185},{n:18,r:310},{n:99,r:435}]:metrics.length>16?[{n:10,r:175},{n:99,r:330}]:[{n:99,r:230}];let cursor=0;for(const ring of rings){const names=metrics.slice(cursor,cursor+ring.n);names.forEach((name,i)=>{const offset=(cursor%2)*0.11,angle=-Math.PI/2+offset+Math.PI*2*i/Math.max(names.length,1);positions[name]=kgPolar(c,c,ring.r,angle)});cursor+=names.length;if(cursor>=metrics.length)break}let edges=base.map((name,i)=>kgEdge(`M ${c} ${c} L ${positions[name].x.toFixed(1)} ${positions[name].y.toFixed(1)}`,'theme',i)).join('');edges+=relations.map((r,i)=>{const a=positions[r.source],b=positions[r.target];if(!a||!b)return '';const mx=(a.x+b.x)/2,my=(a.y+b.y)/2-28;return kgEdge(`M ${a.x.toFixed(1)} ${a.y.toFixed(1)} Q ${mx.toFixed(1)} ${my.toFixed(1)} ${b.x.toFixed(1)} ${b.y.toFixed(1)}`,'metric',i,true)}).join('');const nodes=metrics.map((name,i)=>kgMetricNode(name,positions[name],i,external.includes(name))).join('');return {width:size,height:size,body:edges+kgDirectoryNode(meta.label,'主题',{x:c,y:c},0,'','root')+nodes,description:`主题${meta.label}以辐射布局展示 ${base.length} 个指标、${external.length} 个跨主题关联指标与 ${relations.length} 条指标关系。`}}
function kgForceLayout(nodes,links,width,height){const byId=Object.fromEntries(nodes.map(n=>[n.id,n])),cx=width/2,cy=height/2,topics=nodes.filter(n=>n.type==='topic');nodes.forEach((n,i)=>{n.vx=0;n.vy=0;if(n.type==='root'){n.x=cx;n.y=cy;return}if(n.type==='topic'){const ti=topics.indexOf(n),p=kgPolar(cx,cy,250,-Math.PI/2+Math.PI*2*ti/Math.max(topics.length,1));n.x=p.x;n.y=p.y;return}const parents=links.filter(l=>l.target===n.id&&byId[l.source]?.type==='topic'),parent=byId[parents[0]?.source],mi=i+1,angle=Math.atan2((parent?.y||cy)-cy,(parent?.x||cx)-cx)+(mi%9-4)*.12,r=390+Math.floor((mi%27)/9)*88;n.x=cx+Math.cos(angle)*r;n.y=cy+Math.sin(angle)*r});for(let step=0;step<170;step++){nodes.forEach(n=>{n.fx=(cx-n.x)*.0009;n.fy=(cy-n.y)*.0009});for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){const a=nodes[i],b=nodes[j],dx=b.x-a.x||.01,dy=b.y-a.y||.01,d2=Math.max(64,dx*dx+dy*dy),d=Math.sqrt(d2),min=kgNodeRadius(a.type)+kgNodeRadius(b.type)+14,force=d<min?(min-d)*.055:Math.min(.7,1000/d2),ux=dx/d,uy=dy/d;a.fx-=ux*force;a.fy-=uy*force;b.fx+=ux*force;b.fy+=uy*force}links.forEach(l=>{const a=byId[l.source],b=byId[l.target];if(!a||!b)return;const dx=b.x-a.x,dy=b.y-a.y,d=Math.max(1,Math.sqrt(dx*dx+dy*dy)),target=l.kind==='directory'?235:l.kind==='theme'?118:175,k=l.kind==='metric'?.008:.018,pull=(d-target)*k,ux=dx/d,uy=dy/d;if(a.type!=='root'){a.fx+=ux*pull;a.fy+=uy*pull}b.fx-=ux*pull;b.fy-=uy*pull});nodes.forEach(n=>{if(n.type==='root'){n.x=cx;n.y=cy;return}n.vx=(n.vx+n.fx)*.76;n.vy=(n.vy+n.fy)*.76;const speed=Math.max(1,Math.sqrt(n.vx*n.vx+n.vy*n.vy)),cap=7;n.x+=n.vx*Math.min(1,cap/speed);n.y+=n.vy*Math.min(1,cap/speed);const pad=kgNodeRadius(n.type)+22;n.x=Math.max(pad,Math.min(width-pad,n.x));n.y=Math.max(pad,Math.min(height-pad,n.y))})}return byId}
function kgObjectGraph(meta){const width=1400,height=1180,nodes=[{id:'root',type:'root',label:meta.label}],links=[],metricNames=kgUnique(meta.metrics),topicIds={};meta.topics.forEach((topic,ti)=>{const id=`t:${topic}`;topicIds[topic]=id;nodes.push({id,type:'topic',label:topic,index:ti});links.push({source:'root',target:id,kind:'directory',index:ti});meta.topicMetrics[topic].forEach(metric=>links.push({source:id,target:`m:${metric}`,kind:'theme'}))});metricNames.forEach((name,i)=>nodes.push({id:`m:${name}`,type:'metric',label:name,index:i}));meta.relations.forEach((r,i)=>links.push({source:`m:${r.source}`,target:`m:${r.target}`,kind:'metric',index:i}));const pos=kgForceLayout(nodes,links,width,height);let edges='';links.forEach((l,i)=>{const a=pos[l.source],b=pos[l.target];if(!a||!b)return;const curve=l.kind==='metric'?22:0,path=curve?`M ${a.x.toFixed(1)} ${a.y.toFixed(1)} Q ${((a.x+b.x)/2).toFixed(1)} ${((a.y+b.y)/2-curve).toFixed(1)} ${b.x.toFixed(1)} ${b.y.toFixed(1)}`:`M ${a.x.toFixed(1)} ${a.y.toFixed(1)} L ${b.x.toFixed(1)} ${b.y.toFixed(1)}`;edges+=kgEdge(path,l.kind,i,l.kind==='metric')});const topicNodes=meta.topics.map((topic,ti)=>{const parts=[...meta.scope.parts,topic],attrs=`data-kg-scope-level='4' data-kg-scope-parts='${esc(JSON.stringify(parts))}' aria-label='聚焦主题 ${esc(topic)}'`;return kgDirectoryNode(topic,'主题',pos[topicIds[topic]],ti,attrs,'topic')}).join('');const metricNodes=metricNames.map((name,i)=>kgMetricNode(name,pos[`m:${name}`],i)).join('');return {width,height,body:edges+kgDirectoryNode(meta.label,'对象',pos.root,0,'','root')+topicNodes+metricNodes,description:`对象${meta.label}以力导向布局展示 ${meta.topics.length} 个主题、${meta.metrics.length} 个指标和 ${meta.relations.length} 条指标关系。`}}
function kgGraphSvg(meta){let graph=meta.scope.level<3?kgSimpleLevelGraph(meta):meta.scope.level===3?kgObjectGraph(meta):kgTopicGraph(meta);return `<svg class='kg-svg dynamic' style='width:${graph.width}px;min-width:${Math.min(graph.width,760)}px' viewBox='0 0 ${graph.width} ${graph.height}' role='img' aria-labelledby='kg-graph-title kg-graph-desc'><title id='kg-graph-title'>${esc(meta.label)}知识图谱</title><desc id='kg-graph-desc'>${esc(graph.description)}点击目录节点继续钻取，点击指标查看详细信息。</desc><defs><marker id='kg-arrow' viewBox='0 0 10 10' refX='8' refY='5' markerWidth='6' markerHeight='6' orient='auto-start-reverse'><path d='M 0 0 L 10 5 L 0 10 z'/></marker></defs>${graph.body}</svg>`}
function kgCyModel(meta){const elements=[],nodeIds=new Map();let edgeIndex=0;const addNode=(key,label,kind,extra={})=>{const id=`n${nodeIds.size}`;nodeIds.set(key,id);elements.push({group:'nodes',data:{id,label,kind,...extra},classes:[kind,extra.external?'external':'',extra.selected?'selected':'',extra.related?'related':''].filter(Boolean).join(' ')});return id};const addEdge=(source,target,kind)=>{if(!source||!target)return;elements.push({group:'edges',data:{id:`e${edgeIndex++}`,source,target,kind},classes:kind})};const root=addNode('root',meta.label,'root',{nodeType:meta.type});if(meta.scope.level<3){const next=meta.scope.level+1;kgChildValues(meta.rows,next).forEach(label=>{const parts=[...meta.scope.parts,label],id=addNode(`scope:${parts.join('/')}`,label,next===3?'object':'domain',{scopeLevel:next,scopeParts:JSON.stringify(parts),nodeType:KG_LEVEL_NAMES[next]});addEdge(root,id,'directory')})}else if(meta.scope.level===3){meta.topics.forEach(topic=>{const parts=[...meta.scope.parts,topic],id=addNode(`topic:${topic}`,topic,'topic',{scopeLevel:4,scopeParts:JSON.stringify(parts),nodeType:'主题'});addEdge(root,id,'directory')});meta.metrics.forEach(name=>addNode(`metric:${name}`,name,'metric',{metricName:name,nodeType:'指标',selected:name===state.selectedGraphMetric,related:KG_SOURCE.relations.some(x=>x.source===name||x.target===name)}));meta.topics.forEach(topic=>meta.topicMetrics[topic].forEach(name=>addEdge(nodeIds.get(`topic:${topic}`),nodeIds.get(`metric:${name}`),'theme')));meta.relations.forEach(x=>addEdge(nodeIds.get(`metric:${x.source}`),nodeIds.get(`metric:${x.target}`),'relation'))}else{const base=kgMetrics(meta.label),all=[...base,...meta.external];all.forEach(name=>addNode(`metric:${name}`,name,'metric',{metricName:name,nodeType:meta.external.includes(name)?'跨主题指标':'指标',external:meta.external.includes(name),selected:name===state.selectedGraphMetric,related:KG_SOURCE.relations.some(x=>x.source===name||x.target===name)}));base.forEach(name=>addEdge(root,nodeIds.get(`metric:${name}`),'theme'));meta.relations.forEach(x=>addEdge(nodeIds.get(`metric:${x.source}`),nodeIds.get(`metric:${x.target}`),'relation'))}return elements}
function kgGraphCanvas(meta){const open=Boolean(state.selectedGraphNode);return `<div class='kg-graph-frame'><div class='kg-canvas kg-g6-shell'><div class='kg-graph-toolbar' aria-label='图谱视图控制'><button type='button' data-kg-zoom='in' aria-label='放大图谱'>＋</button><button type='button' data-kg-zoom='out' aria-label='缩小图谱'>−</button><button type='button' data-kg-zoom='fit' aria-label='适应画布'>居中</button></div><div id='kg-cy' class='kg-cy' role='application' aria-label='${esc(meta.label)}知识图谱，可单击节点查看信息、拖拽节点、滚轮缩放和平移画布'></div><p class='sr-only'>图谱提供可缩放的可视化视图，完整关系同时列于下方关系清单。</p></div><aside class='kg-node-drawer ${open?'open':''}' aria-hidden='${open?'false':'true'}' aria-label='节点信息'><header class='kg-node-drawer-head'><div><span>NODE INSPECTOR</span><b>节点信息</b></div><button type='button' data-kg-close-inspector aria-label='关闭节点信息'>×</button></header><div class='kg-details-body'>${kgDetails(meta)}</div></aside></div>`}
function kgSelectMetric(name,graph,nodeId=''){kgSelectGraphNode({label:name,kind:'metric',metricName:name,nodeType:'指标'},graph,nodeId)}
function initKnowledgeGraph(){const container=document.getElementById('kg-cy');if(!container)return;if(window.kgGraph){window.kgGraph.destroy();window.kgGraph=null}if(!window.G6?.Graph){container.innerHTML=`<div class='kg-empty'><h3>图谱组件加载失败</h3><p>请刷新页面后重试。</p></div>`;return}const meta=kgScopeMeta(),data=kgG6Model(meta),force=meta.scope.level<4||data.nodes.length>12;const graph=new G6.Graph({container,data,autoFit:{type:'view',options:{when:'always',direction:'both'}},animation:true,node:{type:'circle',style:d=>d.style,state:{selected:{stroke:'#fff',lineWidth:4,shadowColor:'rgba(255,255,255,.58)',shadowBlur:30}}},edge:{type:'line',style:d=>d.style,state:{highlight:{stroke:'#f2c66d',lineWidth:2.5,opacity:1}}},layout:force?{type:'d3-force',preventOverlap:true,link:{distance:data.nodes.length>70?105:138,strength:.64},manyBody:{strength:data.nodes.length>70?-390:-680},center:{strength:.045},animation:true}:{type:'concentric',preventOverlap:true,nodeSpacing:44,sortBy:'kind',animation:true},behaviors:force?['drag-canvas','zoom-canvas','click-select','drag-element-force']:['drag-canvas','zoom-canvas','click-select','drag-element']});window.kgGraph=graph;container.dataset.nodeCount=String(data.nodes.length);container.dataset.edgeCount=String(data.edges.length);container.dataset.layout=force?'d3-force':'concentric';graph.on(G6.NodeEvent.CLICK,event=>{const datum=graph.getNodeData(event.target.id),info=datum?.data||{};kgSelectGraphNode(info,graph,event.target.id)});document.querySelectorAll('[data-kg-zoom]').forEach(button=>button.onclick=()=>{const action=button.dataset.kgZoom;if(action==='fit')graph.fitView({when:'always',direction:'both'},{duration:320});else graph.zoomBy(action==='in'?1.2:.84,{duration:180})});graph.render().then(()=>graph.fitView({when:'always',direction:'both'},{duration:560})).catch(error=>{console.error(error);container.innerHTML=`<div class='kg-empty'><h3>图谱渲染失败</h3><p>请刷新页面后重试。</p></div>`});kgBindInspectorLinks(graph,data.nodes);kgBindNodeDrawer()}
function kgKindByLevel(level){return ({1:'responsibility',2:'domain',3:'object',4:'topic'})[level]||'metric'}
function kgSetNodeSelection(graph,nodeId){if(!graph||!nodeId)return;try{const selected=graph.getElementDataByState?.('node','selected')||[];selected.forEach(item=>graph.setElementState(item.id,[]));graph.setElementState(nodeId,['selected']);graph.focusElement?.(nodeId,{duration:260})}catch(error){console.warn('G6 selection update skipped',error)}}
