function kgCloseNodeDrawer(){state.selectedGraphNode=null;const drawer=document.querySelector('.kg-node-drawer');if(!drawer)return;drawer.classList.remove('open');drawer.setAttribute('aria-hidden','true')}
function kgBindNodeDrawer(){const drawer=document.querySelector('.kg-node-drawer'),close=document.querySelector('[data-kg-close-inspector]');if(!drawer||!close)return;close.onclick=kgCloseNodeDrawer;drawer.onkeydown=event=>{if(event.key==='Escape'){kgCloseNodeDrawer();document.getElementById('kg-cy')?.focus()}}}
function kgSelectGraphNode(info,graph,nodeId=''){state.selectedGraphNode={...info};state.selectedGraphMetric=info.metricName||'';kgSetNodeSelection(graph,nodeId);const details=document.querySelector('.kg-node-drawer .kg-details-body'),drawer=document.querySelector('.kg-node-drawer');if(details){details.innerHTML=kgDetails(kgScopeMeta());details.scrollTop=0}if(drawer){drawer.classList.add('open');drawer.setAttribute('aria-hidden','false')}kgBindInspectorLinks(graph,graph?.getNodeData?.()||[])}
function kgG6NodeStyle(kind,extra={}){const palette={responsibility:{size:108,fill:'#5947b7',stroke:'#b9afff',label:'#fff',shadow:'rgba(115,93,220,.38)'},domain:{size:96,fill:'#1766a8',stroke:'#83c8ff',label:'#fff',shadow:'rgba(39,142,218,.34)'},object:{size:86,fill:'#087d82',stroke:'#77d9d5',label:'#fff',shadow:'rgba(13,154,157,.3)'},topic:{size:76,fill:'#248467',stroke:'#8ce0bf',label:'#f4fffb',shadow:'rgba(36,132,103,.3)'},metric:{size:64,fill:'#e9b957',stroke:'#ffe0a0',label:'#2f250f',shadow:'rgba(233,185,87,.24)'}};const p=palette[kind]||palette.metric,size=p.size+(extra.isRoot?10:0);return {cursor:'pointer',size,labelText:kgTruncate(extra.label||'',kind==='metric'?12:14),labelPlacement:'center',labelWordWrap:true,labelMaxWidth:size-18,labelFontFamily:'Inter, PingFang SC, Microsoft YaHei, sans-serif',labelFontWeight:700,labelFontSize:kind==='metric'?9:10,labelFill:p.label,fill:p.fill,stroke:p.stroke,lineWidth:extra.isRoot?3.5:2,shadowColor:p.shadow,shadowBlur:extra.isRoot?28:15,shadowOffsetX:0,shadowOffsetY:5}}
function kgG6EdgeStyle(kind){if(kind==='relation')return {stroke:'#e6b85d',lineWidth:1.8,opacity:.9,endArrow:true,endArrowType:'triangle',endArrowSize:6};if(kind==='theme')return {stroke:'#6f9c90',lineWidth:1.25,opacity:.55};return {stroke:'#55acd0',lineWidth:1.55,opacity:.58}}
function kgG6Model(meta){const nodes=[],edges=[],nodeIds=new Map();let edgeIndex=0;const scopeKey=parts=>'scope:'+parts.join('/'),addNode=(key,label,kind,extra={})=>{if(nodeIds.has(key))return nodeIds.get(key);const id='n'+nodeIds.size,data={label,kind,...extra};nodeIds.set(key,id);const selected=extra.metricName?extra.metricName===state.selectedGraphMetric:state.selectedGraphNode?.kind===kind&&state.selectedGraphNode?.label===label;nodes.push({id,data,style:kgG6NodeStyle(kind,{...data,label}),states:selected?['selected']:[]});return id},addEdge=(source,target,kind)=>{if(!source||!target||edges.some(edge=>edge.source===source&&edge.target===target&&edge.data.kind===kind))return;edges.push({id:'e'+edgeIndex++,source,target,data:{kind},style:kgG6EdgeStyle(kind)})};const rootParts=meta.scope.parts,rootKind=kgKindByLevel(meta.scope.level),root=addNode(scopeKey(rootParts),meta.label,rootKind,{scopeLevel:meta.scope.level,scopeParts:JSON.stringify(rootParts),nodeType:meta.type,isRoot:true});meta.rows.forEach(row=>{let parent=root;for(let level=meta.scope.level+1;level<=4;level++){const parts=[];for(let i=1;i<=level;i++)parts.push(row[KG_LEVEL_FIELDS[i]]);const label=row[KG_LEVEL_FIELDS[level]],id=addNode(scopeKey(parts),label,kgKindByLevel(level),{scopeLevel:level,scopeParts:JSON.stringify(parts),nodeType:KG_LEVEL_NAMES[level]});addEdge(parent,id,'directory');parent=id}kgMetrics(row['主题']).forEach(name=>{const id=addNode('metric:'+name,name,'metric',{metricName:name,nodeType:'指标',related:KG_SOURCE.relations.some(x=>x.source===name||x.target===name)});addEdge(parent,id,'theme')})});meta.external.forEach(name=>{const metricId=addNode('metric:'+name,name,'metric',{metricName:name,nodeType:'跨主题指标',external:true,related:true});kgMetricTopics(name).filter(topic=>topic!==meta.label).forEach(topic=>{const parts=[...meta.scope.parts.slice(0,3),topic],topicId=addNode('external-topic:'+topic,topic,'topic',{scopeLevel:4,scopeParts:JSON.stringify(parts),nodeType:'关联主题'});addEdge(topicId,metricId,'theme')})});meta.relations.forEach(x=>addEdge(nodeIds.get('metric:'+x.source),nodeIds.get('metric:'+x.target),'relation'));return {nodes,edges}}
function kgGraphCanvas(meta){const open=Boolean(state.selectedGraphNode);return `<div class='kg-graph-frame'><div class='kg-canvas kg-g6-shell'><div class='kg-graph-toolbar' aria-label='图谱视图控制'><button type='button' data-kg-zoom='in' aria-label='放大图谱'>＋</button><button type='button' data-kg-zoom='out' aria-label='缩小图谱'>−</button><button type='button' data-kg-zoom='fit' aria-label='适应画布'>居中</button></div><div id='kg-cy' class='kg-cy' role='application' tabindex='0' aria-label='${esc(meta.label)}知识图谱，可单击节点查看信息、拖拽节点、滚轮缩放和平移画布'></div><p class='sr-only'>可缩放的知识图谱视图。</p></div><aside class='kg-node-drawer ${open?'open':''}' aria-hidden='${open?'false':'true'}' aria-label='节点信息'><header class='kg-node-drawer-head'><div><span>NODE INSPECTOR</span><b>节点信息</b></div><button type='button' data-kg-close-inspector aria-label='关闭节点信息'>×</button></header><div class='kg-details-body'>${kgDetails(meta)}</div></aside></div>`}
function kgSelectMetric(name,graph,nodeId=''){kgSelectGraphNode({label:name,kind:'metric',metricName:name,nodeType:'指标'},graph,nodeId)}
function initKnowledgeGraph(){const container=document.getElementById('kg-cy');if(!container)return;if(window.kgGraph){window.kgGraph.destroy();window.kgGraph=null}if(!window.G6?.Graph){container.innerHTML=`<div class='kg-empty'><h3>图谱组件加载失败</h3><p>请刷新页面后重试。</p></div>`;return}const meta=kgScopeMeta(),data=kgG6Model(meta),force=meta.scope.level<4||data.nodes.length>12;const graph=new G6.Graph({container,data,autoFit:{type:'view',options:{when:'always',direction:'both'}},animation:true,node:{type:'circle',style:d=>d.style,state:{selected:{stroke:'#fff',lineWidth:4,shadowColor:'rgba(255,255,255,.58)',shadowBlur:30}}},edge:{type:'line',style:d=>d.style,state:{highlight:{stroke:'#f2c66d',lineWidth:2.5,opacity:1}}},layout:force?{type:'d3-force',preventOverlap:true,link:{distance:data.nodes.length>70?105:138,strength:.64},manyBody:{strength:data.nodes.length>70?-390:-680},center:{strength:.045},animation:true}:{type:'concentric',preventOverlap:true,nodeSpacing:44,sortBy:'kind',animation:true},behaviors:force?['drag-canvas','zoom-canvas','click-select','drag-element-force']:['drag-canvas','zoom-canvas','click-select','drag-element']});window.kgGraph=graph;container.dataset.nodeCount=String(data.nodes.length);container.dataset.edgeCount=String(data.edges.length);container.dataset.layout=force?'d3-force':'concentric';graph.on(G6.NodeEvent.CLICK,event=>{const datum=graph.getNodeData(event.target.id),info=datum?.data||{};kgSelectGraphNode(info,graph,event.target.id)});document.querySelectorAll('[data-kg-zoom]').forEach(button=>button.onclick=()=>{const action=button.dataset.kgZoom;if(action==='fit')graph.fitView({when:'always',direction:'both'},{duration:320});else graph.zoomBy(action==='in'?1.2:.84,{duration:180})});graph.render().then(()=>graph.fitView({when:'always',direction:'both'},{duration:560})).catch(error=>{console.error(error);container.innerHTML=`<div class='kg-empty'><h3>图谱渲染失败</h3><p>请刷新页面后重试。</p></div>`});kgBindInspectorLinks(graph,data.nodes);kgBindNodeDrawer()}
function kgValue(value){return value&&String(value).trim()?String(value).trim():'—'}
function kgDetailRows(info){const groups=[['基础信息',['指标来源','指标是否已注册','分析视角']],['分析定义',['分析维度','分析度量','分析方法','下钻路径']],['规则与策略',['指标规则','策略大类','策略子类','策略内容','策略用途']]];return groups.map(([title,fields])=>`<section class='kg-detail-group'><h4>${title}</h4>${fields.map(field=>`<div class='kg-detail-row'><small>${field}</small><p class='${field==='指标规则'||field==='策略内容'?'pre':''}'>${esc(kgValue(info[field]))}</p></div>`).join('')}</section>`).join('')}
function kgDetails(meta){const chosen=state.selectedGraphNode,metric=chosen?.metricName||state.selectedGraphMetric;if(metric){const info=KG_SOURCE.metricInfo[metric]||{},links=KG_SOURCE.relations.filter(x=>x.source===metric||x.target===metric);return `<div class='kg-detail-head entity-metric'><span><i></i>指标详情</span><b>${esc(metric)}</b><div><span class='status ${kgValue(info['指标是否已注册'])==='是'?'ok':'warn'}'>${kgValue(info['指标是否已注册'])==='是'?'已注册':'未注册'}</span><span class='kg-rel-count'>${links.length} 条指标关系</span></div></div>${kgDetailRows(info)}${links.length?`<section class='kg-detail-group'><h4>指标关系</h4><div class='kg-related-list'>${links.map(x=>{const incoming=x.target===metric,other=incoming?x.source:x.target;return `<button type='button' data-metric-node='${esc(other)}'><span>${incoming?'上游':'下游'}</span><b>${esc(other)}</b></button>`}).join('')}</div></section>`:''}`}const level=chosen?.scopeLevel||meta.scope.level,parts=chosen?.scopeParts?JSON.parse(chosen.scopeParts):meta.scope.parts,label=chosen?.label||parts[level-1]||meta.label,rows=kgRowsForParts(parts),topics=kgChildValues(rows,4),metrics=kgUnique(topics.flatMap(kgMetrics)),relations=KG_SOURCE.relations.filter(x=>metrics.includes(x.source)||metrics.includes(x.target)),children=level<4?kgChildValues(rows,level+1):kgMetrics(label),kind=chosen?.kind||kgKindByLevel(level),path=parts.join(' / ');return `<div class='kg-detail-head entity-${kind}'><span><i></i>${KG_LEVEL_NAMES[level]}信息</span><b>${esc(label)}</b><div><span class='kg-entity-code'>L${level}</span><span class='kg-rel-count'>${children.length} 个直属下级</span></div></div><section class='kg-entity-overview'><div><small>目录路径</small><p>${esc(path)}</p></div><dl><div><dt>${children.length}</dt><dd>直属下级</dd></div><div><dt>${topics.length}</dt><dd>下属主题</dd></div><div><dt>${metrics.length}</dt><dd>关联指标</dd></div><div><dt>${relations.length}</dt><dd>指标关系</dd></div></dl></section>${children.length?`<section class='kg-detail-group'><h4>${level===4?'主题指标':'下层实例'}</h4><div class='kg-child-tags'>${children.slice(0,24).map(name=>`<span>${esc(name)}</span>`).join('')}${children.length>24?`<small>另有 ${children.length-24} 项</small>`:''}</div></section>`:''}`}
function kgAdjacency(meta){const data=kgG6Model(meta),byId=Object.fromEntries(data.nodes.map(node=>[node.id,node])),typeName=kind=>({responsibility:'责任中心',domain:'业务域',object:'对象',topic:'主题',metric:'指标'})[kind]||kind,rows=data.edges.map(edge=>{const a=byId[edge.source]?.data,b=byId[edge.target]?.data,relation=edge.data.kind==='relation'?'关联指标':edge.data.kind==='theme'?'包含指标':'包含';return [typeName(a?.kind),a?.label||'—',relation,typeName(b?.kind),b?.label||'—']});return `<details class='kg-adjacency'><summary><span>关系清单</span><small>无障碍替代视图 · ${rows.length} 条关系</small></summary><div class='table-wrap'><table class='data-table'><thead><tr><th>起点类型</th><th>起点</th><th>关系</th><th>终点类型</th><th>终点</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x[0])}</td><td>${esc(x[1])}</td><td>${esc(x[2])}</td><td>${esc(x[3])}</td><td>${x[3]==='指标'?`<button class='kg-table-link' data-metric-node='${esc(x[4])}'>${esc(x[4])}</button>`:esc(x[4])}</td></tr>`).join('')}</tbody></table></div></details>`}
function knowledgeGraphGovernance(stage,item){
  const isApproval=stage==='approval',meta=kgScopeMeta();
  if(!meta.metrics.includes(state.selectedGraphMetric)&&!meta.external.includes(state.selectedGraphMetric))state.selectedGraphMetric='';
  const action=`<button class='btn' data-action='back-work-queue'>← 返回待${isApproval?'审批':'审核'}列表</button>${isApproval?`<button class='btn' data-action='preview-evidence'>查看专家审核记录</button>`:''}`;
return `${context()}${pageHead(`${isApproval?'STAGE 05 · 领域知识责任人':'STAGE 04 · 领域知识专家'}`,isApproval?'知识审批':'知识审核',`图谱核对“${item.name}”的目录、主题、指标与关系。`,action)}<div class='selected-work-item'><span class='structured'>◇</span><div><small>${item.kind}</small><b>${esc(item.name)}</b><p>${esc(item.source)} · ${item.count} 条知识 · ${isApproval?'审核已通过':`提交人 ${esc(item.owner)}`}</p></div>${badge(isApproval?'审批中':'审核中')}</div><section class='kg-summary'><div><span>当前图谱范围 · ${meta.type}</span><b>${esc(meta.path)}</b></div><dl><div><dt>${meta.topics.length}</dt><dd>范围主题</dd></div><div><dt>${meta.metrics.length}</dt><dd>范围指标</dd></div><div><dt>${meta.relations.length}</dt><dd>指标关系</dd></div><div><dt>${KG_SOURCE.meta.uniqueMetrics||0}</dt><dd>全部指标</dd></div></dl></section><div class='kg-workbench'><aside class='panel kg-directory'><div class='panel-head'><div><h3>知识目录</h3><small>L1 责任中心 · L2 业务域 · L3 对象 · L4 主题</small></div></div><div class='kg-directory-body'>${kgDirectoryTree()}</div></aside><section class='panel kg-canvas-panel'><div class='panel-head'><div><h3>智能分析知识图谱</h3><small>${meta.type}范围 · ${meta.topics.length} 个主题 · ${meta.metrics.length} 个指标</small></div><div class='kg-legend'><span><i class='responsibility'></i>责任中心</span><span><i class='domain'></i>业务域</span><span><i class='object'></i>对象</span><span><i class='theme'></i>主题</span><span><i class='metric'></i>指标</span><span><i class='relation'></i>关系</span></div></div>${kgGraphCanvas(meta)}</section></div>${isApproval?`<section class='panel kg-opinion'><div class='panel-head'><div><h3>审批意见</h3></div><span class='status ${state.approved?'ok':'warn'}'>${state.approved?'审批通过':'待填写'}</span></div><div class='panel-body'><div class='form-field'><label>领域知识责任人意见</label><textarea placeholder='请输入审批意见'>${state.approved?'审批通过：目录、主题与指标关系准确，可进入认证。':'目录层级清晰，主题与指标关系准确，建议通过审批。'}</textarea></div></div></section>`:''}<div class='action-bar'><span class='spacer'></span>${isApproval?`<button class='btn danger' data-action='reject-owner'>退回知识专家</button><button class='btn success' data-action='approve-owner'>审批通过并提交认证 →</button>`:`<button class='btn primary' data-action='submit-approval'>审核完成，提交知识审批 →</button>`}</div>`
}
function reviewGraphPage(){const item=workQueueData('review').find(x=>x.id===state.reviewWorkItem);if(!item)return workQueuePage('review','知识审核','领域知识专家','统一查看待审核的原始知识集与结构化知识集，选择知识集后进入对应审核工作台。');return item.type==='structured'?knowledgeGraphGovernance('review',item):reviewV3()}
function approvalGraphPage(){const item=workQueueData('approval').find(x=>x.id===state.approvalWorkItem);if(!item)return workQueuePage('approval','知识审批','领域知识责任人','集中查看专家审核通过的知识集，原始知识使用列表审批，结构化知识使用图谱审批。');return item.type==='structured'?knowledgeGraphGovernance('approval',item):approvalV4()}
